# Method source: official engine PR #22, b87f32e. This inventory is traced
# through the package's SOURCE driver with Julia 1.12.7, not the compiled entry.
# Resolve generated callable types by structure; their names are not an API.
function metal_host_closure_type(owner::Module, captured::Tuple)
    matches = Set{Any}()
    for name in names(owner; all=true)
        isdefined(owner, name) || continue
        value = getfield(owner, name)
        value isa Type || continue
        type = Base.unwrap_unionall(value)
        if type isa DataType && type <: Function && !isabstracttype(type) && fieldnames(type) == captured
            push!(matches, Base.typename(type).wrapper)
        end
    end
    return only(matches)
end

function metal_host_device_callable_type(argument_shape::Type)
    # The device inventory already identifies the fill and broadcast kernels.
    # Match their argument shape rather than their generated callable names.
    return only(Set(typeof(f) for (f, arguments) in metal_kernel_signatures()
                    if arguments <: argument_shape))
end

function precompile_metal_host_signatures()
    successes = 0
    failures = 0
    try
        for (index, signature) in enumerate(metal_host_signatures())
            try
                precompile(signature) || error("No matching host method")
                successes += 1
            catch exception
                failures += 1
                @warn "BEAT Metal host precompile failed" index signature exception=(exception, catch_backtrace())
            end
        end
    catch exception
        failures += 1
        @warn "BEAT Metal host inventory could not be loaded" exception=(exception, catch_backtrace())
    end
    @info "BEAT Metal host workload complete" compiled_signatures=successes failures
end

function metal_host_local_closure_type(f, arguments::Type, captured::Tuple; depth=1)
    # Nested lock/get! callbacks can capture the same fields. Scope the search
    # to the enclosing method and the requested nesting depth, using lowered
    # type references, never the generated binding's spelling.
    methods = [which(f, arguments)]
    matches = Set{Any}()
    for level in 1:depth
        empty!(matches)
        next_methods = Method[]
        function visit(value)
            if value isa QuoteNode
                visit(value.value)
            elseif value isa Expr
                foreach(visit, value.args)
            else
                type = value isa GlobalRef && isdefined(value.mod, value.name) ?
                    getfield(value.mod, value.name) : value
                if type isa Type
                    body = Base.unwrap_unionall(type)
                    if body isa DataType && body <: Function && !isabstracttype(body) &&
                       parentmodule(body) === parentmodule(f)
                        fieldnames(body) == captured && push!(matches, Base.typename(body).wrapper)
                        if level < depth
                            method = try
                                which(Tuple{type})
                            catch
                                nothing
                            end
                            method === nothing || push!(next_methods, method)
                        end
                    end
                end
            end
        end
        for method in methods
            foreach(visit, Base.uncompressed_ast(method).code)
        end
        methods = unique(next_methods)
    end
    return only(matches)
end

function metal_host_signatures()
