    bundle = @__MODULE__
    regular = core.MetalRegularAssemblyCache{Float32,Nothing}
    singular = core.MetalSingularCorrectionCache{Float32}
    field = core.MetalFieldEvaluationCache{Float32}
    weak_get = metal_host_local_closure_type(get!,
        Tuple{Function,WeakKeyDict,Any}, (:default, :wkh, :key))
    weak_pop = metal_host_local_closure_type(pop!,
        Tuple{WeakKeyDict,Any,Any}, (:wkh, :key, :default))
    launch_body = typeof(Base.bodyfunction(which(core._metal_launch, Tuple{Function,Int})))
    buffer_body = typeof(Base.bodyfunction(which(Metal.MTL.MTLBuffer,
        Tuple{Metal.MTL.MTLDevice,Int,Ptr{ComplexF32}})))
    kernel_body = typeof(Base.bodyfunction(which(Tuple{Metal.HostKernel})))
    kernel_pool = metal_host_closure_type(Metal, (:groups, :threads, :queue, :submit, :kernel, :args))
    point_generator = metal_host_local_closure_type(core._metal_fast_field_tables_for,
        Tuple{field}, (:points,); depth=3)
    normal_generator = metal_host_local_closure_type(core._metal_fast_field_tables_for,
        Tuple{field}, (:normals,); depth=3)
    rule_generator = metal_host_local_closure_type(core._metal_fused_singular_tables_for,
        Tuple{regular,singular}, (:n, :rp, :tp); depth=3)
    packed_builder = metal_host_local_closure_type(core._metal_packed_pair_tables_for,
        Tuple{regular}, (:cache,); depth=2)
    group_releaser = metal_host_local_closure_type(core._release_metal_fused_singular_tables!,
        Tuple{singular}, (); depth=1)
    fill_kernel = metal_host_device_callable_type(
        Tuple{Metal.KernelAbstractions.CompilerMetadata,Metal.MtlDeviceArray,ComplexF32})
